const cloned = deepClone(obj);
cloned.b.c = 3;
console.log(obj.b.c); // 2 (original unchanged)

const obj1 = { a: 1, b: { c: 2 } };
const obj2 = { b: { d: 3 }, e: 4 };
const obj3 = { e: 5, f: 6 };
deepMergeMany(obj1, obj2, obj3); // { a: 1, b: { c: 2, d: 3 }, e: 5, f: 6 }

const object = {foo: {bar: 'a'}};
deleteObjectPropertyByPath(object, 'foo.bar');
console.log(object);
//=> {foo: {}}

object.foo.bar = {x: 'y', y: 'x'};
deleteObjectPropertyByPath(object, 'foo.bar.x');
console.log(object);
//=> {foo: {bar: {y: 'x'}}}

const object = {foo: {bar: 'a'}};
deleteProperty(object, 'foo.bar');
console.log(object);
//=> {foo: {}}

object.foo.bar = {x: 'y', y: 'x'};
deleteProperty(object, 'foo.bar.x');
