type KeysToCamelCase<T> = T extends Builtin ? T : T extends (...args: unknown[]) => unknown ? T : T extends readonly unknown[] ? number extends T['length'] ? KeysToCamelCase<T[number]>[] : TupleToCamelCase<T> : T extends object ? {
    [K in keyof T as K extends string ? ToCamelCase<K> : K]: KeysToCamelCase<T[K]>;
} : T;

type KeysToSnakeCase<T> = T extends Builtin ? T : T extends (...args: unknown[]) => unknown ? T : T extends readonly unknown[] ? number extends T['length'] ? KeysToSnakeCase<T[number]>[] : TupleToSnakeCase<T> : T extends object ? {
    [K in keyof T as K extends string ? ToSnakeCase<K> : K]: KeysToSnakeCase<T[K]>;
} : T;

