interface PaginatedResult<TItem> {
    items: TItem[];
    total: number;
    page: number;
    itemsPerPage: number;
    totalPages: number;
    hasNextPage: boolean;
    hasPreviousPage: boolean;
}

interface PaginationInput {
    page?: number;
    itemsPerPage?: number;
}

interface PaginationOffsets {
    offset: number;
    limit: number;
    page: number;
    itemsPerPage: number;
}
